// Общие шаги для импорта клиентов из CSV Workiz (#4030e4; план specs/clients-import.md). PROD, admin, компания «test», EN.
// CSV собирается в тесте (Buffer, без файла на диске): клиенты «QA-Import <метка> …» с уникальными телефонами/e-mail (иначе дедуп пропустит строки).
// Разметка — по скриншотам 4030e4-import-*.png (17.11): окно «Import clients», «Found in the file», «Also import» (Notes / Tags / Workiz client ID),
// «Preview», «N new clients will be added.» / «… already on file will be skipped.», «Import N clients», «Import finished / N clients added.».
// Не сверено с сайтом при записи: input[type=file] внутри окна (setInputFiles на скрытое поле), подпись кнопки «Import clients» на /customers.
import { expect, Locator, Page } from '@playwright/test';
import { TEST_COMPANY_ID } from '../dispatch-sms/dispatch-helpers';

export const ROLE = 'admin';
export { TEST_COMPANY_ID };

export const stamp = () => Date.now().toString(36).slice(-5);
const digits4 = () => String(1000 + Math.floor(Math.random() * 9000));

export type Row = { first: string; last: string; company?: string; phone: string; phone2?: string; email: string; address: string; city: string; state: string; zip: string; tags?: string; id: string; mobile?: string };

/** Три клиента Workiz «All clients». ZIP с ведущим нулём: 02108 (Boston), 07302 (Jersey City). */
export function workizRows(mark: string): Row[] {
  return [
    { first: `QA-Import ${mark}`, last: 'Alpha', company: `QA-Import ${mark} Co`, phone: `(305) 555-${digits4()}`, email: `qa-import-${mark}-a@example.test`, address: '120 NW 2nd Ave', city: 'Miami', state: 'FL', zip: '33128', tags: 'VIP', id: `WZ-${mark}-1` },
    { first: `QA-Import ${mark}`, last: 'Bravo', phone: `(617) 555-${digits4()}`, phone2: `(617) 555-${digits4()}`, email: `qa-import-${mark}-b@example.test`, address: '45 Beacon St', city: 'Boston', state: 'MA', zip: '02108', tags: 'Repeat', id: `WZ-${mark}-2` },
    { first: `QA-Import ${mark}`, last: 'Charlie', phone: `(201) 555-${digits4()}`, email: `qa-import-${mark}-c@example.test`, address: '10 Exchange Pl', city: 'Jersey City', state: 'NJ', zip: '07302', tags: '"Commercial, Fleet"', id: `WZ-${mark}-3` },
  ];
}

/** CSV в формате Workiz Reports → Clients → All clients (колонки как в файле из ручной проверки workiz-all-clients.csv). */
export function workizCsv(rows: Row[]): Buffer {
  const head = 'Client ID,First name,Last name,Company name,Primary phone,Secondary phone,Email,Address,City,State,Zip code,Tags';
  const lines = rows.map((r) => [r.id, r.first, r.last, r.company ?? '', r.phone, r.phone2 ?? '', r.email, r.address, r.city, r.state, r.zip, r.tags ?? ''].join(','));
  return Buffer.from([head, ...lines].join('\n'), 'utf8');
}

/** CSV с колонкой «Mobile», которой нет среди известных (нераспознанная колонка). */
export function mobileCsv(mark: string): Buffer {
  const head = 'First name,Last name,Primary phone,Email,Zip code,Mobile';
  const rows = [
    `QA-Import ${mark} Mobile,Delta,(305) 555-${digits4()},qa-import-${mark}-d@example.test,02134,3055550184`,
    `QA-Import ${mark} Mobile,Echo,(305) 555-${digits4()},qa-import-${mark}-e@example.test,07030,3055550185`,
  ];
  return Buffer.from([head, ...rows].join('\n'), 'utf8');
}

/** Компания «test» до загрузки страницы, EN. */
export async function prepare(page: Page, lang: 'en' | 'he' = 'en') {
  await page.addInitScript(([l, c]) => {
    try {
      window.localStorage.setItem('preferred-language', l);
      window.localStorage.setItem('selected-company-id', c);
    } catch { /* ignore */ }
  }, [lang, TEST_COMPANY_ID] as const);
}

export const importDialog = (page: Page): Locator => page.getByRole('dialog').filter({ hasText: 'Import clients' }).first();

/** /customers → Import clients → выбрать файл → окно с превью. */
export async function openImportWithFile(page: Page, name: string, content: Buffer): Promise<Locator> {
  await page.goto('/customers');
  await expect.poll(() => page.evaluate(() => window.localStorage.getItem('selected-company-id')), { message: 'выбрана компания «test»' }).toBe(TEST_COMPANY_ID);
  await page.getByRole('button', { name: 'Import clients' }).first().click();
  const dialog = importDialog(page);
  await expect(dialog).toBeVisible();
  await dialog.locator('input[type="file"]').setInputFiles({ name, mimeType: 'text/csv', buffer: content });
  await expect(dialog.getByText('Found in the file')).toBeVisible({ timeout: 20_000 });
  return dialog;
}

/** Очистка (не роняет тест): клиенты «QA-Import <метка> …» → Actions → Delete Customer. */
export async function deleteImported(page: Page, mark: string) {
  if (page.isClosed()) return;
  try {
    for (let i = 0; i < 6; i++) {
      await page.goto('/customers');
      await page.getByPlaceholder('Search clients...').fill(`QA-Import ${mark}`);
      const hit = page.getByText(new RegExp(`^QA-Import ${mark}`)).filter({ visible: true }).first();
      if (!(await hit.isVisible({ timeout: 8_000 }).catch(() => false))) return;
      await hit.click();
      await page.waitForURL(/\/CustomerDetail/);
      await page.getByRole('button', { name: 'Actions' }).filter({ visible: true }).first().click();
      page.once('dialog', (d) => d.accept().catch(() => {}));
      await page.getByRole('menuitem', { name: 'Delete Customer' }).click();
      await page.waitForURL(/\/Customers/i);
    }
  } catch (e) {
    console.warn(`очистка клиентов «QA-Import ${mark}» не удалась — удалить вручную: ${String(e).slice(0, 200)}`);
  }
}
